<?php require 'config.php'; $pageTitle='Create your profile'; $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ $name=trim($_POST['name']??''); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $role=($_POST['role']??'seeker')==='employer'?'employer':'seeker'; if($name && $email){ $_SESSION['user']=['name'=>$name,'email'=>$email,'role'=>$role,'profile'=>$_POST]; header('Location: dashboard.php'); exit; } $error='Please enter your name and a valid email address.'; } require 'includes/header.php'; ?>
<section class="onboard-wrap"><div class="onboard-intro"><span class="eyebrow">LET'S GET TO KNOW YOU</span><h1>Make your next move <em>your own.</em></h1><p>Build your profile in a few simple steps. You can add more details later.</p><div class="step-list"><div class="step active"><b>01</b><span><strong>Basic details</strong><small>Start with the essentials</small></span></div><div class="step"><b>02</b><span><strong>Your pathway</strong><small>Job seeker or employer</small></span></div><div class="step"><b>03</b><span><strong>Career details</strong><small>Tell us what you're looking for</small></span></div></div></div>
<div class="form-card"><div class="progress-track"><span></span></div><form method="post" id="onboardForm"><div class="wizard-panel active" data-step="0"><span class="eyebrow">STEP 1 OF 3</span><h2>First, the basics</h2><p class="muted">What should we call you?</p><?php if($error): ?><div class="alert"><?=e($error)?></div><?php endif; ?><label>Full name<input name="name" required placeholder="Your full name"></label><label>Email address<input type="email" name="email" required placeholder="you@example.com"></label><label>Password<input type="password" name="password" required minlength="6" placeholder="At least 6 characters"></label></div>
<div class="wizard-panel" data-step="1"><span class="eyebrow">STEP 2 OF 3</span><h2>Which brings you here?</h2><p class="muted">Choose the experience you want to start with.</p><div class="role-cards"><label class="role-card"><input type="radio" name="role" value="seeker" checked><span class="role-icon">↗</span><strong>I'm looking for work</strong><small>Explore jobs, apply and manage invitations.</small></label><label class="role-card"><input type="radio" name="role" value="employer"><span class="role-icon">▣</span><strong>I'm hiring</strong><small>Post roles and meet suitable candidates.</small></label></div></div>
<div class="wizard-panel" data-step="2"><span class="eyebrow">STEP 3 OF 3</span><h2>Tell us a little more</h2><p class="muted">You can update these details anytime.</p><label>Location<input name="location" placeholder="e.g. Ahmedabad, Gujarat"></label><label>Industry of interest<select name="industry"><option value="">Choose an industry</option><option>Technology</option><option>Business & Finance</option><option>Marketing</option><option>Design</option><option>Healthcare</option><option>Education</option><option>Other</option></select></label><label>Employment preference<select name="employment_type"><option value="">Choose preference</option><option>Full-time</option><option>Part-time</option><option>Internship</option><option>Contract</option><option>Trainee</option></select></label></div>
<div class="wizard-actions"><button type="button" class="btn btn-outline" id="prev" hidden>← Back</button><span class="grow"></span><button type="button" class="btn btn-primary" id="next">Continue →</button><button class="btn btn-primary" id="finish" hidden>Create profile ✓</button></div></form><p class="tiny-note">By continuing, you agree to the demo terms and privacy notice.</p></div></section>
<script>
(()=>{let n=0;const panels=[...document.querySelectorAll('.wizard-panel')],steps=[...document.querySelectorAll('.step')],prev=document.querySelector('#prev'),next=document.querySelector('#next'),finish=document.querySelector('#finish'),bar=document.querySelector('.progress-track span');function render(){panels.forEach((p,i)=>p.classList.toggle('active',i===n));steps.forEach((s,i)=>{s.classList.toggle('active',i===n);s.classList.toggle('done',i<n)});prev.hidden=n===0;next.hidden=n===2;finish.hidden=n!==2;bar.style.width=((n+1)/3*100)+'%'}function valid(){for(const el of panels[n].querySelectorAll('input,select')){if(el.type==='radio')continue;if(!el.checkValidity()){el.reportValidity();return false}}return true}next.onclick=()=>{if(valid()){n++;render()}};prev.onclick=()=>{n--;render()};document.querySelector('#onboardForm').onsubmit=e=>{if(!valid())e.preventDefault()};render()})();
</script>
